start = time.perf_counter()   # 点①:发起前
ttft_ms = None
for chunk in stream:
    delta = chunk.choices[0].delta.content
    if not delta:
        continue              # role 块/心跳块不算首 token
    if ttft_ms is None:
        ttft_ms = (time.perf_counter() - start) * 1000  # 点②:首块
total_ms = (time.perf_counter() - start) * 1000     # 点③:流结束
